    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Sort intervals by start position
    a = sorted(a)
    b = sorted(b)

    # Merge overlapping intervals in a
    merged_a = []
    for start, end in a:
        if merged_a and start <= merged_a[-1][1]:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in merged_a:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    # Partial or complete overlap
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if curr_end > b_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort and merge touching intervals
    result = sorted(result)
    final_result = []
